import React, { useState } from 'react';
import './Creations.css';

function Creations() {
  // State for managing which image is currently selected in galleries
  const [activeImageIndex, setActiveImageIndex] = useState({});

  // Helper function to set active image for a specific gallery
  const setActiveImage = (galleryId, index) => {
    setActiveImageIndex(prev => ({
      ...prev,
      [galleryId]: index
    }));
  };

  // Art project data organized by folders
  const artProjects = [
    {
      id: "city-street",
      title: "City Street, 2025",
      description: "",
      type: "image",
      imagePath: "/Asset/Random Art/City Street/City Street.png",
      imageTitle: "City Street"
    },
    {
      id: "frames",
      title: "Frames, 2025",
      description: "",
      type: "image",
      imagePath: "/Asset/Random Art/Frames/Frames.png",
      imageTitle: "Frames"
    },
    {
      id: "journal-comic",
      title: "Journal Comic, 2024",
      description: "",
      type: "pdf",
      pdfPath: "/Asset/Random Art/Journal Comic/Tim_Book_cut.pdf",
    },
    {
      id: "memory-dream",
      title: "Memory and Dream, 2024",
      description: "",
      type: "dual-image",
      images: [
        {
          path: "/Asset/Random Art/Memory and Dream/Memory.jpg",
          title: "Memory, Monotype"
        },
        {
          path: "/Asset/Random Art/Memory and Dream/Dream.jpg",
          title: "Dream, Relief"
        }
      ]
    },
    {
      id: "tarot-cards",
      title: "Tarot Cards, 2025",
      description: "",
      type: "gallery",
      images: [
        {
          path: "/Asset/Random Art/Tarot Drawings/Strength.png",
          title: "Strength"
        },
        {
          path: "/Asset/Random Art/Tarot Drawings/Chariot.png",
          title: "Chariot"
        },
        {
          path: "/Asset/Random Art/Tarot Drawings/Wheel.png",
          title: "Wheel of Fortune"
        },
        {
          path: "/Asset/Random Art/Tarot Drawings/Hermit.png",
          title: "Hermit"
        }
      ]
    },
    {
      id: "posters",
      title: "Soft Rains Poster, 2025",
      description: "",
      type: "image",
      imagePath: "/Asset/Random Art/Posters/Soft.png",
      imageTitle: "Soft Rains"
    },
    {
      id: "sea-storm",
      title: "Sea Storm, 2025",
      description: "",
      type: "image",
      imagePath: "/Asset/Random Art/Sea Storm/storm.jpg",
      imageTitle: "Sea Storm"
    }
  ];

  // Render different content based on type (pdf, image, or gallery)
  const renderContent = (project) => {
    switch (project.type) {
      case 'pdf':
        return (
          <div className="art-pdf-container">
            <div className="pdf-preview">
              <object 
                data={process.env.PUBLIC_URL + project.pdfPath + '#page=1'} 
                type="application/pdf"
                className="pdf-object"
              >
                <div className="pdf-fallback">
                  <p>PDF preview not available</p>
                </div>
              </object>
            </div>
            <div className="art-actions">
              <a 
                href={process.env.PUBLIC_URL + project.pdfPath} 
                target="_blank" 
                rel="noopener noreferrer"
                className="paper-btn btn-primary"
              >
                View PDF
              </a>
              <a 
                href={process.env.PUBLIC_URL + project.pdfPath} 
                download
                className="paper-btn btn-secondary"
              >
                Download
              </a>
            </div>
          </div>
        );
      
      case 'image':
        return (
          <div className="art-image-container">
            <img 
              src={process.env.PUBLIC_URL + project.imagePath} 
              alt={project.imageTitle} 
              className="art-single-image"
            />
            <div className="image-caption">{project.imageTitle}</div>
          </div>
        );
      
      case 'dual-image':
        return (
          <div className="art-dual-image-container">
            <div className="dual-image-wrapper">
              <div className="dual-image-item">
                <img 
                  src={process.env.PUBLIC_URL + project.images[0].path} 
                  alt={project.images[0].title} 
                  className="art-dual-image"
                />
                <div className="image-caption">{project.images[0].title}</div>
              </div>
              <div className="dual-image-item">
                <img 
                  src={process.env.PUBLIC_URL + project.images[1].path} 
                  alt={project.images[1].title} 
                  className="art-dual-image"
                />
                <div className="image-caption">{project.images[1].title}</div>
              </div>
            </div>
          </div>
        );
      
      case 'gallery':
        // Get current active image index or default to 0
        const currentIndex = activeImageIndex[project.id] || 0;
        
        return (
          <div className="art-gallery-container">
            <div className="gallery-main-image">
              <img 
                src={process.env.PUBLIC_URL + project.images[currentIndex].path} 
                alt={project.images[currentIndex].title}
                className="gallery-featured-image" 
              />
              <div className="image-caption">{project.images[currentIndex].title}</div>
            </div>
            
            <div className="gallery-thumbnails">
              {project.images.map((image, index) => (
                <div 
                  key={index} 
                  className={`gallery-thumbnail ${index === currentIndex ? 'active' : ''}`}
                  onClick={() => setActiveImage(project.id, index)}
                >
                  <img 
                    src={process.env.PUBLIC_URL + image.path} 
                    alt={image.title}
                  />
                </div>
              ))}
            </div>
          </div>
        );
      
      default:
        return <p>Content not available</p>;
    }
  };

  return (
    <div className="about-canvas">
      <div className="about-content">
        <h2 className="about-title">Art Showcase</h2>
        <p className="art-intro">
          A collection of my drawings, paintings, and other artistic creations
        </p>
        
        <div className="art-projects">
          {artProjects.map((project) => (
            <div key={project.id} className="art-project-card">
              <h3 className="art-project-title">{project.title}</h3>
              <p className="art-project-description">{project.description}</p>
              
              <div className="art-project-content">
                {renderContent(project)}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

export default Creations;
